mapper.select:
SELECT id
FROM learning_plan_draft
WHERE expires_at <= #{expiredBefore}
ORDER BY expires_at, id
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.delete:
DELETE FROM learning_plan_draft
WHERE id IN

    #{draftId}

mapper.update:
UPDATE learning_plan
SET status = #{status},
    title = #{title},
    plan_json = #{planJson, typeHandler=org.congcong.algomentor.agent.persistence.postgres.json.JsonbTypeHandler},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE learning_plan
SET title = #{title},
    plan_json = #{planJson, typeHandler=org.congcong.algomentor.agent.persistence.postgres.json.JsonbTypeHandler},
    updated_at = #{updatedAt}
WHERE id = #{planId}
  AND user_id = #{userId}

mapper.select:
SELECT plan.id AS plan_id, CAST( COUNT(DISTINCT (phase.phase_index, problem.slug)) FILTER (WHERE problem.id IS NOT NULL) AS INTEGER ) AS total_problem_count, CAST( COUNT(DISTINCT (phase.phase_index, problem.slug)) FILTER (WHERE progress.status = 'COMPLETED') AS INTEGER ) AS completed_problem_count FROM learning_plan plan LEFT JOIN learning_plan_phase phase ON phase.plan_id = plan.id LEFT JOIN learning_plan_recommended_problem problem ON problem.phase_id = phase.id LEFT JOIN learning_plan_problem_progress progress ON progress.user_id = plan.user_id AND progress.plan_id = plan.id AND progress.phase_index = phase.phase_index AND progress.problem_slug = problem.slug WHERE plan.user_id = #{userId} AND plan.id IN
#{planId}
GROUP BY plan.id

SELECT COUNT(*)
FROM learning_plan
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM learning_plan
WHERE user_id = #{userId}
  AND status = #{status}

SELECT MAX(created_at)
FROM learning_plan
WHERE user_id = #{userId}

mapper.update:
UPDATE learning_plan_draft
SET confirmed_plan_id = NULL,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND confirmed_plan_id = #{planId}

mapper.delete:
DELETE FROM learning_plan
WHERE id = #{id}
  AND user_id = #{userId}

mapper.update:
UPDATE learning_plan_proposal_group
SET status = #{status},
    initial_instruction = #{initialInstruction},
    latest_proposal_id = #{latestProposalId},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE learning_plan_proposal_group
SET status = #{discardedStatus},
    updated_at = #{updatedAt}
WHERE id = #{proposalGroupId}
  AND user_id = #{userId}
  AND proposal_type = 'PLAN_EXTENSION'
  AND target_type = 'PLAN'
  AND target_id = #{planId}
  AND status = #{activeStatus}

mapper.select:
SELECT COALESCE(MAX(revision_no), 0) + 1
FROM learning_plan_draft_revision
WHERE proposal_group_id = #{proposalGroupId}

SELECT COALESCE(MAX(revision_no), 0) + 1
FROM learning_plan_extension_revision
WHERE proposal_group_id = #{proposalGroupId}

UPDATE learning_plan_draft_revision
SET status = 'SUPERSEDED',
    updated_at = #{updatedAt}
WHERE proposal_group_id = #{proposalGroupId}
  AND id != #{exceptRevisionId}
  AND status = 'READY'
RETURNING id

UPDATE learning_plan_extension_revision
SET status = 'SUPERSEDED',
    updated_at = #{updatedAt}
WHERE proposal_group_id = #{proposalGroupId}
  AND id != #{exceptRevisionId}
  AND status = 'READY'
RETURNING id

SELECT COALESCE(MAX(phase_index), 0)
FROM learning_plan_phase
WHERE plan_id = #{planId}
